changeSet.sql:
ALTER TABLE patient_services_and_products DROP CONSTRAINT IF EXISTS ck_psp_item_reference_by_type;
ALTER TABLE patient_services_and_products ADD CONSTRAINT ck_psp_item_reference_by_type CHECK ( ( billing_item_type = 'MEDICATION' AND brand_medication_id IS NOT NULL AND diagnostic_test_id IS NULL AND service_id IS NULL AND procedure_id IS NULL AND vaccine_brand_id IS NULL ) OR ( billing_item_type IN ('LABORATORY', 'RADIOLOGY', 'PATHOLOGY') AND brand_medication_id IS NULL AND diagnostic_test_id IS NOT NULL AND service_id IS NULL AND procedure_id IS NULL AND vaccine_brand_id IS NULL ) OR ( billing_item_type = 'SERVICE' AND brand_medication_id IS NULL AND diagnostic_test_id IS NULL AND service_id IS NOT NULL AND procedure_id IS NULL AND vaccine_brand_id IS NULL ) OR ( billing_item_type = 'PROCEDURE' AND brand_medication_id IS NULL AND diagnostic_test_id IS NULL AND service_id IS NULL AND procedure_id IS NOT NULL AND vaccine_brand_id IS NULL ) OR ( billing_item_type = 'VACCINE' AND brand_medication_id IS NULL AND diagnostic_test_id IS NULL AND service_id IS NULL AND procedure_id IS NULL AND vaccine_brand_id IS NOT NULL ) );
ALTER TABLE billing_charge_line DROP CONSTRAINT IF EXISTS ck_billing_charge_line_item_reference;
ALTER TABLE billing_charge_line ADD CONSTRAINT ck_billing_charge_line_item_reference CHECK ( ( billing_item_type = 'MEDICATION' AND brand_medication_id IS NOT NULL AND diagnostic_test_id IS NULL AND service_id IS NULL AND procedure_id IS NULL AND vaccine_brand_id IS NULL ) OR ( billing_item_type IN ('LABORATORY', 'RADIOLOGY', 'PATHOLOGY') AND brand_medication_id IS NULL AND diagnostic_test_id IS NOT NULL AND service_id IS NULL AND procedure_id IS NULL AND vaccine_brand_id IS NULL ) OR ( billing_item_type = 'SERVICE' AND brand_medication_id IS NULL AND diagnostic_test_id IS NULL AND service_id IS NOT NULL AND procedure_id IS NULL AND vaccine_brand_id IS NULL ) OR ( billing_item_type = 'PROCEDURE' AND brand_medication_id IS NULL AND diagnostic_test_id IS NULL AND service_id IS NULL AND procedure_id IS NOT NULL AND vaccine_brand_id IS NULL ) OR ( billing_item_type = 'VACCINE' AND brand_medication_id IS NULL AND diagnostic_test_id IS NULL AND service_id IS NULL AND procedure_id IS NULL AND vaccine_brand_id IS NOT NULL ) );
